/* Signature Haitian Creole Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Jeanrose": "From Jean + Rose.", "Mariepierre": "From Marie + Pierre.", "Jacquesrose": "From Jacques + Rose.", "Pierremarie": "From Pierre + Marie.", "Dieudonnerose": "From Dieudonne + Rose.", "Roselourde": "From Rose + Lourde.", "Jeanrosemond": "Signature compound surname.", "Mariepierrot": "Signature compound surname.", "Roselafleur": "From rose + la fleur: Signature surname, 'the flower'.", "Pierrelouisemond": "Signature compound surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Jeanrose';
console.log(lookup(q));

